{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울시 조례상 지정 금연구역에서 불붙은 담배만 소지해도 금연 위반인지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 금연환경 조성 및 간접흡연 피해방지조례 제2조제2호는 \"흡연\"을 담배를 피우는 행위뿐 아니라 불이 붙은 담배를 소지하는 것도 포함한다고 정의한다. 같은 조례 제5조제4항은 누구든지 제5조제1항에 따라 지정된 금연구역에서 흡연을 해서는 아니된다고 정하고 있으므로, 담배를 피우지 않더라도 불붙은 담배를 들고 있는 행위는 흡연에 해당하여 금연구역 내 금연 위반이 된다.",
          "b_ids": "금연:제2조제2호, 금연:제5조제4항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
